function promptShiftViewAuth(shiftData) {
    return new Promise((resolve) => {
        const overlay = document.getElementById('shiftAuthModal');
        const select = document.getElementById('shiftAuthUserSelect');
        const pinInput = document.getElementById('shiftAuthPinInput');
        const submitBtn = document.getElementById('shiftAuthSubmitBtn');
        const cancelBtn = document.getElementById('shiftAuthCancelBtn');
        const errorEl = document.getElementById('shiftAuthError');
        const targetShiftEl = document.getElementById('shiftAuthTargetShift');

        targetShiftEl.textContent = `📅 ${shiftData.date || '--'} (${shiftData.shift_name || '--'} by ${shiftData.employee_name || '--'})`;
        pinInput.value = '';
        errorEl.style.display = 'none';
        errorEl.textContent = '';
        submitBtn.disabled = false;
        submitBtn.textContent = '✓ Unlock & View';

        // Populate select with Admins and Employees
        select.innerHTML = '<option value="">Select your name...</option>';
        
        const adminGroup = document.createElement('optgroup');
        adminGroup.label = '👑 Admins';
        ['Rafay', 'Jahanzaib Khan'].forEach(name => {
            const opt = document.createElement('option');
            opt.value = name;
            opt.textContent = `👑 ${name}`;
            adminGroup.appendChild(opt);
        });
        select.appendChild(adminGroup);

        const empGroup = document.createElement('optgroup');
        empGroup.label = '👤 Employees';
        const empList = (config.employees || []).length ? config.employees : (settingsData.employees || []);
        empList.forEach(name => {
            if (name !== 'Rafay' && name !== 'Jahanzaib Khan') {
                const opt = document.createElement('option');
                opt.value = name;
                opt.textContent = `👤 ${name}`;
                empGroup.appendChild(opt);
            }
        });
        select.appendChild(empGroup);

        let resolved = false;
        const close = () => {
            if (resolved) return;
            resolved = true;
            overlay.classList.remove('show');
            cleanup();
            resolve(null);
        };

        const showError = (msg) => {
            errorEl.textContent = msg;
            errorEl.style.display = msg ? '' : 'none';
        };

        function _keydown(e) {
            if (e.key === 'Enter' && !submitBtn.disabled) submitBtn.click();
        }

        submitBtn.onclick = async () => {
            const user_name = select.value;
            const pin = pinInput.value;
            if (!user_name) {
                showError('Please select your name');
                return;
            }
            if (!pin || pin.length < 4 || !/^\d+$/.test(pin)) {
                showError('Enter a valid 4-20 digit PIN');
                return;
            }

            showError('');
            submitBtn.disabled = true;
            submitBtn.textContent = '⏳ Verifying...';

            try {
                const res = await fetch(`/api/shifts/${shiftData.shift_id}/view`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json', ..._authHeaders() },
                    body: JSON.stringify({ user_name: user_name, pin: pin })
                });
                const data = await res.json();
                if (!res.ok || !data.success) {
                    showError(data.error || 'Access denied');
                    pinInput.value = '';
                    pinInput.focus();
                    submitBtn.disabled = false;
                    submitBtn.textContent = '✓ Unlock & View';
                    return;
                }

                // Success!
                if (data.role === 'admin' && data.token) {
                    _setAdminSession(data.token, data.user_name);
                }
                resolved = true;
                overlay.classList.remove('show');
                cleanup();
                resolve(data.shift);
            } catch (err) {
                showError('Connection error, please try again');
                submitBtn.disabled = false;
                submitBtn.textContent = '✓ Unlock & View';
            }
        };

        cancelBtn.onclick = close;
        const _overlayClick = (e) => { if (e.target === overlay) close(); };
        overlay.addEventListener('click', _overlayClick);
        pinInput.addEventListener('keydown', _keydown);
        select.addEventListener('keydown', _keydown);

        function cleanup() {
            overlay.removeEventListener('click', _overlayClick);
            pinInput.removeEventListener('keydown', _keydown);
            select.removeEventListener('keydown', _keydown);
        }

        overlay.classList.add('show');
        select.focus();
    });
}

async function showShiftDetail(shiftData) {
    if (shiftData.status === 'active') {
        renderClosedShiftView(shiftData);
        showClosedShiftView(true);
        return;
    }

    // Shift is closed:
    // If admin is already logged in, request directly with X-Admin-Token
    if (isAdminLoggedIn()) {
        try {
            const res = await fetch(`/api/shifts/${shiftData.shift_id}/view`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', ..._authHeaders() }
            });
            const data = await res.json();
            if (data.success) {
                renderClosedShiftView(data.shift);
                showClosedShiftView(true);
                return;
            }
        } catch(e) {}
    }

    // Prompt user credentials and verify inside the modal
    const shift = await promptShiftViewAuth(shiftData);
    if (!shift) return;

    renderClosedShiftView(shift);
    showClosedShiftView(true);
}

