async function startNewShift() {
    if (currentShift && currentShift.shift_id) {
        showToast('A shift is already active. Close it before starting a new one.', 'error');
        return;
    }

    const employee = document.getElementById('employeeSelect').value;
    if (!employee) {
        showToast('Please select an employee name first', 'error');
        return;
    }

    try {
        const res = await fetch('/api/shift/start', {
            method: 'POST',
            headers: {'Content-Type':'application/json'},
            body: JSON.stringify({employee_name: employee})
        });
        const data = await res.json();
        if (data.success) {
            currentShift = data.shift;
            // Migrate pre-start draft to the new shift_id
            migrateLocalDraft(null, currentShift.shift_id);
            setStatus('active', `Shift Active - ${employee}`);
            const shiftName = document.getElementById('shiftSelect').value.split(' (')[0];
            showToast(`New ${shiftName} shift started!`, 'success');
            _persistPendingSessions();
            clearForm();
            if (data.last_shift && data.last_shift.inventory) {
                data.last_shift.inventory.forEach(i => {
                    const name = i[0];
                    const closing = parseInt(i[3]) || 0;
                    const el = document.querySelector(`.inv-opening[data-item="${escHtml(name)}"]`);
                    if (el) {
                        el.value = closing;
                        const r = el.closest('tr');
                        if (r) recalcInvSold(r.querySelector('.inv-closing'));
                    }
                });
            } else if (data.shift && data.shift.inventory) {
                data.shift.inventory.forEach(i => {
                    const name = i[0];
                    const opening = parseInt(i[1]) || 0;
                    const el = document.querySelector(`.inv-opening[data-item="${escHtml(name)}"]`);
                    if (el) {
                        el.value = opening;
                        const r = el.closest('tr');
                        if (r) recalcInvSold(r.querySelector('.inv-closing'));
                    }
                });
            }
            carryOverEligiblePendingToForm();
            document.getElementById('employeeSelect').value = employee;
            syncDropdown(document.getElementById('employeeSelect'));
            showFormView();
            if (tabCoordinator) tabCoordinator.activate(currentShift.shift_id);
            triggerAutoSave();
        } else {
            showToast(data.error || 'Failed to start shift', 'error');
        }
    } catch (e) {
        showToast('Server error. Is the backend running?', 'error');
    }
}

function pcNameSelected(el) {
    const val = el.value;
    if (val) {
        const body = el.closest('tbody');
        const dup = Array.from(body.querySelectorAll('.pkg-name')).some(o => o !== el && o.value === val);
        if (dup) {
            showToast('PC ' + val + ' is already added to this section', 'error');
            el.value = '';
            syncDropdown(el);
            recalcTotals();
            return;
        }
    }
    recalcTotals();
    const amt = el.closest('tr').querySelector('.pkg-amount');
    if (amt && amt._cd) { amt._cd.open(); amt._cd.trigger.focus(); }
}

function addPackageRow(type) {
    const body = document.getElementById(type === 'morning' ? 'morningBody' : 'nighterBody');
    const totalPCs = config.total_pcs || 27;
    const pcOpts = Array.from({length:totalPCs}, (_, i) => `<option value="PC #${i+1}">PC #${i+1}</option>`).join('');
    const pkgOpts = sortPackages(config.packages).map(p => `<option value="${p.price}">${escHtml(p.hz)} ${escHtml(p.hrs)} - PKR ${p.price}</option>`).join('');
    const row = document.createElement('tr');
    row.innerHTML = `
        <td><select class="pkg-name" onchange="pcNameSelected(this)"><option value="">PC #</option>${pcOpts}</select></td>
        <td><select class="pkg-amount" onchange="recalcTotals()"><option value="">Select Package</option>${pkgOpts}</select></td>
        <td><button class="btn-del-row" onclick="this.closest('tr').remove(); recalcTotals();">✕</button></td>`;
    body.appendChild(row);
    initCustomDropdowns(row);
    initPkgAmountEnter(row, type);
    const firstSelect = row.querySelector('.pkg-name');
    if (firstSelect && firstSelect._cd) { firstSelect._cd.open(); firstSelect._cd.trigger.focus(); }
    recalcTotals();
}

function initPkgAmountEnter(row, type) {
    // Only applies to legacy .cd-trigger elements (previously used for amount)
    const triggers = row.querySelectorAll('.cd-trigger');
    triggers.forEach(t => {
        if (t.previousElementSibling && t.previousElementSibling.classList.contains('pkg-amount')) {
            t.addEventListener('keydown', function(e) {
                const menu = this.querySelector('.cd-menu');
                if (e.key === 'Enter' && (!menu || menu.style.display === 'none' || getComputedStyle(menu).display === 'none')) {
                    e.preventDefault();
                    e.stopPropagation();
                    addPackageRow(type);
                }
            });
        }
    });
}

function recalcTotals() {
    const calc = (bodyId, totalId) => {
        let t = 0;
        document.getElementById(bodyId).querySelectorAll('.pkg-amount').forEach(i => t += parseFloat(i.value) || 0);
        document.getElementById(totalId).textContent = t.toFixed(2);
        return t;
    };
    const m = calc('morningBody','morningTotal');
    const n = calc('nighterBody','nighterTotal');
    document.getElementById('summaryMorning').textContent = m.toFixed(2);
    document.getElementById('summaryNighter').textContent = n.toFixed(2);
    autoCalcPS5(); autoCalcExpenses(); recalcGrandTotal();
}

function calcPS5Amount(ctrl, hours, isExtendedOnly, ps5Number) {
    const c = Math.max(1, parseInt(ctrl) || 1);
    const h = Math.max(1, parseInt(hours) || 1);
    const pricing = (config.ps5_pricing || {});
    // PC tier: per-controller flat rate
    if (ps5Number === 'PC') {
        const pcRate = pricing.ps5_pc_rate || 250;
        return c * pcRate * h;
    }
    const rate2First = pricing.two_controllers_first_hour || 700;
    const rate1First = pricing.one_controller_first_hour || 400;
    const rate2Ext = pricing.two_controllers_extended || 500;
    const rate1Ext = pricing.one_controller_extended || 300;
    const bundlesOfTwo = Math.floor(c / 2);
    const bundlesOfOne = c % 2;
    const firstHour = (bundlesOfTwo * rate2First) + (bundlesOfOne * rate1First);
    const extended = (bundlesOfTwo * rate2Ext) + (bundlesOfOne * rate1Ext);
    if (isExtendedOnly) {
        return extended * h;
    }
    return firstHour + ((h - 1) * extended);
}

function recalcPS5RowAmount(el) {
    const row = el.closest ? el.closest('tr') : el;
    if (row.dataset.amountManual === 'true') return;
    const ctrl = parseInt(row.querySelector('.ps5-ctrl')?.value) || 1;
    const dur = parseInt(row.querySelector('.ps5-duration')?.value) || 1;
    const isExtendedOnly = row.dataset.isExtended === 'true';
    const ps5Num = row.querySelector('.ps5-number')?.value || '';
    const amt = calcPS5Amount(ctrl, dur, isExtendedOnly, ps5Num);
    const amtInput = row.querySelector('.ps5-amount');
    amtInput.value = amt.toFixed(2);
    amtInput.classList.remove('ps5-amount-manual');
    row.dataset.amountManual = 'false';
}

