function calcPS5EndTime(el) {
    const row = el.closest ? el.closest('tr') : el;
    // Invalidate the pinned endDateMs: start/duration changed, so the alarm
    // must re-pin from the new time (see syncTimerRegistry).
    delete row.dataset.endMs;
    const rId = row.dataset.rowId;
    if (rId && ps5EndPins[rId] !== undefined) { delete ps5EndPins[rId]; _saveEndPins(); }
    const startVal = row.querySelector('.ps5-start')?.value;
    const durVal = parseInt(row.querySelector('.ps5-duration')?.value) || 1;
    if (!startVal) return;
    const [h, m] = startVal.split(':').map(Number);
    const totalMinutes = h * 60 + m + durVal * 60;
    const endH = Math.floor(totalMinutes / 60) % 24;
    const endM = totalMinutes % 60;
    row.querySelector('.ps5-end').value = `${String(endH).padStart(2,'0')}:${String(endM).padStart(2,'0')}`;
    row.dataset.alarmTriggered = 'false';
    if (rId) {
        const qIdx = ps5AlarmQueue.indexOf(rId);
        if (qIdx >= 0) ps5AlarmQueue.splice(qIdx, 1);
        const pend = ps5PendingSessions.find(p => p.id === rId);
        if (pend) {
            pend.alarmTriggered = false;
            _savePendingSessions();
        }
    }
    syncTimerRegistry();
}

