function recalcInvSold(el) {
    const row = el.closest('tr');
    const opening = parseInt(row.querySelector('.inv-opening')?.value) || 0;
    const restock = parseInt(row.querySelector('.inv-restock')?.value) || 0;
    const closing = parseInt(row.querySelector('.inv-closing')?.value) || 0;
    const sold = Math.max(0, opening + restock - closing);
    row.querySelector('.inv-sold').value = sold;
    triggerAutoSave();
}

function escHtml(s) {
    return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
}

function recalcGrandTotal() {
    const gv = id => parseFloat(document.getElementById(id)?.value) || 0;
    const gt = id => parseFloat((document.getElementById(id)?.textContent||'').replace(/,/g,'')) || 0;

    const topup = gv('topupInput');
    const morning = gt('summaryMorning');
    const nighter = gt('summaryNighter');
    const ps = gt('summaryPS');
    const cafeteria = gv('cafeteriaInput');
    const expenses = gt('summaryExpenses');

    const grand = topup + morning + nighter + ps + cafeteria;
    document.getElementById('grandTotal').textContent = `PKR ${grand.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}`;

    const cash = gv('cashInput');
    const online = gv('onlineInput');
    const posAmount = gv('actualPosInput');
    const totalPaid = cash + online + posAmount;
    const payTarget = grand - expenses;

    const iconEl = document.getElementById('paymentStatusIcon');
    const labelEl = document.getElementById('paymentStatusLabel');
    const diffEl = document.getElementById('paymentStatusDiff');
    const cashBar = document.getElementById('cashBar');
    const onlineBar = document.getElementById('onlineBar');
    const posBar = document.getElementById('posBar');
    document.getElementById('cashDisplay').textContent = `PKR ${cash.toFixed(0)}`;
    document.getElementById('onlineDisplay').textContent = `PKR ${online.toFixed(0)}`;
    document.getElementById('posDisplay').textContent = `PKR ${posAmount.toFixed(0)}`;

    if (Math.abs(totalPaid - payTarget) < 0.01 && payTarget > 0) {
        iconEl.textContent = '\u2713';
        labelEl.textContent = 'Matched';
        labelEl.style.color = 'var(--gold)';
        diffEl.textContent = `Balanced (PKR ${totalPaid.toFixed(0)})`;
        diffEl.style.color = 'var(--gold)';
    } else if (payTarget === 0 && totalPaid === 0) {
        iconEl.textContent = '\u23F3';
        labelEl.textContent = 'Waiting';
        labelEl.style.color = 'var(--text-dim)';
        diffEl.textContent = 'Enter values to match Grand Total minus Expenses';
        diffEl.style.color = 'var(--text-dim)';
    } else {
        const diff = payTarget - totalPaid;
        iconEl.textContent = '\u2717';
        labelEl.textContent = 'Mismatch';
        labelEl.style.color = 'var(--danger)';
        const dir = diff > 0 ? 'short' : 'excess';
        diffEl.textContent = `${diff > 0 ? 'Short' : 'Excess'} by PKR ${Math.abs(diff).toFixed(0)}`;
        diffEl.style.color = 'var(--danger)';
    }

    const barMax = Math.max(cash, online, posAmount, 1);
    cashBar.style.width = `${(cash / barMax) * 100}%`;
    cashBar.style.background = 'var(--gold)';
    onlineBar.style.width = `${(online / barMax) * 100}%`;
    onlineBar.style.background = 'var(--gold-bright)';
    posBar.style.width = `${(posAmount / barMax) * 100}%`;
    posBar.style.background = '#c4941a';
    triggerAutoSave();
    return grand;
}

let autoSaveTimer = null;

function buildShiftPayload() {
    const employee = document.getElementById('employeeSelect').value;
    const cash = parseFloat(document.getElementById('cashInput').value) || 0;
    const online = parseFloat(document.getElementById('onlineInput').value) || 0;
    const grandText = document.getElementById('grandTotal').textContent.replace(/[^0-9.-]/g,'');
    const grandTotal = parseFloat(grandText) || 0;
    const shiftVal = document.getElementById('shiftSelect').value;
    const [shiftName, shiftTimingRaw] = shiftVal.split(' (');
    const shiftTiming = shiftTimingRaw ? shiftTimingRaw.replace(')','') : '';
    const pkgData = (bodyId) => {
        const d = [];
        document.getElementById(bodyId).querySelectorAll('tr').forEach(r => {
            const n = r.querySelector('.pkg-name')?.value?.trim();
            const a = parseFloat(r.querySelector('.pkg-amount')?.value) || 0;
            if (n) {
                const pkg = (config.packages || []).find(p => p.price === a);
                d.push({pc_name: n, amount: a, hz: pkg ? pkg.hz : '', hrs: pkg ? pkg.hrs : ''});
            }
        });
        return d;
    };
    return {
        employee_name: employee,
        date: currentShift?.date || config.current_date,
        day: currentShift?.day || config.current_day,
        shift_name: shiftName,
        shift_timing: shiftTiming,
        shift_id: currentShift?.shift_id || '',
        opened_at: currentShift?.opened_at || new Date().toISOString().slice(0,19).replace('T',' '),
        financial_summary: {
            topup: parseFloat(document.getElementById('topupInput').value) || 0,
            cafeteria: parseFloat(document.getElementById('cafeteriaInput').value) || 0,
            morning_pkg: parseFloat(document.getElementById('summaryMorning').textContent) || 0,
            nighter_pkg: parseFloat(document.getElementById('summaryNighter').textContent) || 0,
            ps_sale: parseFloat(document.getElementById('summaryPS').textContent) || 0,
            total_expenses: parseFloat(document.getElementById('summaryExpenses').textContent) || 0,
            grand_total: grandTotal,
            cash_received: cash,
            online_payments: online,
            actual_pos_amount: parseFloat(document.getElementById('actualPosInput').value) || 0,
            total_tax_amount: parseFloat(document.getElementById('totalTaxAmountInput').value) || 0
        },
        morning_packages: pkgData('morningBody'),
        nighter_packages: pkgData('nighterBody'),
        ps5_sessions: (() => {
            const d = [];
            document.getElementById('ps5Body').querySelectorAll('tr').forEach(r => {
                const n = r.querySelector('.ps5-number')?.value?.trim();
                if (!n) return;
                d.push({
                    ps_number: n,
                    controllers: Math.max(1, parseInt(r.querySelector('.ps5-ctrl')?.value) || 1),
                    start_time: r.querySelector('.ps5-start')?.value || '',
                    end_time: r.querySelector('.ps5-end')?.value || '',
                    duration_hours: parseInt(r.querySelector('.ps5-duration')?.value) || 1,
                    amount: parseFloat(r.querySelector('.ps5-amount')?.value) || 0,
                    is_extended: r.dataset.isExtended === 'true',
                    row_id: r.dataset.rowId || '',
                    amount_manual: r.dataset.amountManual === 'true'
                });
            });
            return d;
        })(),
        inventory: (() => {
            const d = [];
            document.querySelectorAll('#inventoryBody tr').forEach(r => {
                const name = r.querySelector('.inv-opening')?.dataset?.item;
                if (!name) return;
                d.push({
                    name: name,
                    opening_stock: parseInt(r.querySelector('.inv-opening')?.value) || 0,
                    restock_qty: parseInt(r.querySelector('.inv-restock')?.value) || 0,
                    closing_stock: parseInt(r.querySelector('.inv-closing')?.value) || 0
                });
            });
            return d;
        })(),
        expenses: (() => {
            const d = [];
            document.getElementById('expenseBody').querySelectorAll('tr').forEach(r => {
                const desc = r.querySelector('.exp-desc')?.value?.trim();
                const amt = parseFloat(r.querySelector('.exp-amount')?.value) || 0;
                if (desc) d.push({description: desc, amount: amt});
            });
            return d;
        })(),
        inventory_items_snapshot: (() => {
            const items = [];
            document.querySelectorAll('#inventoryBody tr .inv-opening').forEach(el => {
                const name = el.dataset?.item;
                if (name) items.push(name);
            });
            return items;
        })(),
        form_screenshot_filename: currentShift?.form_screenshot_filename || '',
        pancafe_screenshot_filename: currentShift?.pancafe_screenshot_filename || '',
        last_modified: currentShift?.last_modified || 0
    };
}

/* Convert API-format payload (objects) to storage-format (arrays) for localStorage.
   This matches ShiftData.to_dict() format so populateFormFromShift works. */
function payloadToStorageFormat(payload) {
    if (!payload) return payload;
    const out = { ...payload };
    // packages: [{pc_name, amount, hz, hrs}] -> [[pc_name, amount, hz, hrs]]
    out.morning_packages = (payload.morning_packages || []).map(p => [p.pc_name, p.amount, p.hz, p.hrs]);
    out.nighter_packages = (payload.nighter_packages || []).map(p => [p.pc_name, p.amount, p.hz, p.hrs]);
    // ps5_sessions: [{ps_number, controllers, start_time, end_time, duration_hours, amount, is_extended, row_id, amount_manual}] 
    // -> [ps_number, controllers, start_time, end_time, amount, duration_hours, is_extended?1:0, row_id, amount_manual?1:0]
    out.ps5_sessions = (payload.ps5_sessions || []).map(s => [
        s.ps_number, s.controllers, s.start_time, s.end_time,
        s.amount, s.duration_hours, s.is_extended ? 1 : 0, s.row_id, s.amount_manual ? 1 : 0
    ]);
    // inventory: [{name, opening_stock, restock_qty, closing_stock}] -> [[name, opening_stock, restock_qty, closing_stock]]
    out.inventory = (payload.inventory || []).map(i => [i.name, i.opening_stock, i.restock_qty, i.closing_stock]);
    // expenses: [{description, amount}] -> [[description, amount]]
    out.expenses = (payload.expenses || []).map(e => [e.description, e.amount]);
    return out;
}

function triggerAutoSave() {
    if (!currentShift) return;
    const payload = buildShiftPayload();
    saveLocalDraft(payload);  // Immediate local persistence (zero-loss)
    clearTimeout(autoSaveTimer);
    autoSaveTimer = setTimeout(doAutoSave, 2000);
}

async function doAutoSave() {
    if (!currentShift || !currentShift.shift_id) return;
    const payload = buildShiftPayload();
    const maxRetries = 3;
    let serverReachable = false;
    for (let attempt = 0; attempt < maxRetries; attempt++) {
        if (attempt > 0) {
            await new Promise(r => setTimeout(r, 1000 * Math.pow(2, attempt - 1)));
        }
        try {
            const res = await fetch('/api/shift/auto-save', {
                method: 'POST', headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({shift: payload})
            });
            serverReachable = true;
            if (res.status === 409) {
                // Server has newer data - fetch it and reconcile
                console.warn('Auto-save rejected (stale), reloading from server');
                const res2 = await fetch('/api/shifts/' + currentShift.shift_id);
                if (res2.ok) {
                    const data = await res2.json();
                    if (data.success && data.shift) {
                        const serverShift = data.shift;
                        const serverTs = serverShift.last_modified || 0;
                        const localDraft = loadLocalDraft(currentShift.shift_id);
                        const localTs = localDraft?._local_ts || localDraft?.last_modified || 0;
                        
                        // Only overwrite local draft if server is actually newer
                        if (serverTs >= localTs) {
                            saveLocalDraft(serverShift);
                            populateFormFromShift(serverShift);
                            currentShift = { ...currentShift, ...serverShift };
                        } else {
                            // Local is newer - keep local draft, don't overwrite
                            console.log('Local draft newer than server, keeping local changes');
                        }
                    }
                }
                hideOfflineIndicator();
                return;
            }
            if (res.ok) {
                // Echo the server-side last_modified so the next save passes
                // the staleness guard (the server timestamp is authoritative).
                const data = await res.json().catch(() => ({}));
                if (data && typeof data.last_modified === 'number' && currentShift) {
                    currentShift.last_modified = data.last_modified;
                    // Sync local draft timestamp to server timestamp
                    const draftKey = _getDraftKey(currentShift.shift_id);
                    try {
                        localStorage.setItem(draftKey + DRAFT_TS_SUFFIX, data.last_modified.toString());
                    } catch (e) {}
                }
                hideOfflineIndicator();
                return;
            }
            console.warn(`Auto-save attempt ${attempt+1} failed:`, res.statusText);
        } catch(e) {
            console.error(`Auto-save attempt ${attempt+1} failed:`, e);
        }
    }
    if (!serverReachable) {
        // Offline - keep local draft, show subtle indicator
        showOfflineIndicator();
    } else {
        showToast('Auto-save failed after 3 attempts', 'error');
    }
}

let offlineIndicatorShown = false;
function showOfflineIndicator() {
    if (offlineIndicatorShown) return;
    offlineIndicatorShown = true;
    const el = document.getElementById('offlineIndicator');
    if (el) {
        el.style.display = 'inline-flex';
    } else {
        // Create a simple indicator
        const indicator = document.createElement('span');
        indicator.id = 'offlineIndicator';
        indicator.style.cssText = 'margin-left:8px;padding:2px 8px;background:var(--danger);color:white;border-radius:4px;font-size:11px;';
        indicator.textContent = '● Offline - saved locally';
        const header = document.querySelector('.header-right');
        if (header) header.appendChild(indicator);
    }
}

function hideOfflineIndicator() {
    if (!offlineIndicatorShown) return;
    offlineIndicatorShown = false;
    const el = document.getElementById('offlineIndicator');
    if (el) el.style.display = 'none';
}

async function captureAndUploadScreenshot() {
    if (typeof domtoimage === 'undefined') {
        console.warn('domtoimage not loaded, form screenshot skipped');
        showToast('Form screenshot unavailable (library not loaded)', 'warning');
        return;
    }
    const el = document.getElementById('shiftFormView');
    const section = el.querySelector('.screenshot-section');
    const prevDisplay = section ? section.style.display : null;
    let restored = false;
    const restoreSection = () => {
        if (!restored && section) {
            section.style.display = prevDisplay || '';
            restored = true;
        }
    };
    try {
        if (section) section.style.display = 'none';
        const captureOpts = {
            bgColor: '#0a0a0a',
            style: {
                overflow: 'visible',
                maxHeight: 'none',
                height: 'auto'
            },
            onclone: (clonedDoc) => {
                clonedDoc.querySelectorAll('.table-wrap').forEach(el => {
                    el.style.maxHeight = 'none';
                    el.style.overflow = 'visible';
                });
                clonedDoc.querySelectorAll('.package-col, .sections-grid, .split-row').forEach(el => {
                    el.style.overflow = 'visible';
                });
            }
        };
        const blob = await domtoimage.toBlob(el, captureOpts);
        restoreSection();
        if (!blob || blob.size < 100) {
            console.warn('Form screenshot blob too small, retrying...');
            await new Promise(r => setTimeout(r, 500));
            const retryBlob = await domtoimage.toBlob(el, captureOpts);
            if (!retryBlob || retryBlob.size < 100) {
                showToast('Form screenshot capture failed (blob too small)', 'warning');
                return;
            }
            const fd = new FormData();
            fd.append('image', retryBlob, 'shift_full_form.png');
            fd.append('type', 'form');
            if (currentShift) fd.append('shift_id', currentShift.shift_id);
            const res = await fetch('/api/upload-screenshot', { method: 'POST', body: fd });
            const data = await res.json();
            if (data.success && currentShift) {
                currentShift.form_screenshot_filename = data.filename;
                showToast('Form screenshot captured', 'success');
            } else {
                showToast('Form screenshot upload failed', 'warning');
            }
            return;
        }
        const fd = new FormData();
        fd.append('image', blob, 'shift_full_form.png');
        fd.append('type', 'form');
        if (currentShift) fd.append('shift_id', currentShift.shift_id);
        const res = await fetch('/api/upload-screenshot', { method: 'POST', body: fd });
        const data = await res.json();
        if (data.success && currentShift) {
            currentShift.form_screenshot_filename = data.filename;
            showToast('Form screenshot captured', 'success');
        } else {
            showToast('Form screenshot upload failed', 'warning');
        }
    } catch (e) {
        console.warn('Auto-screenshot capture failed:', e);
        showToast('Form screenshot capture error', 'warning');
    } finally {
        restoreSection();
    }
}

async function _ensurePancafeUploaded() {
    const img = document.getElementById('screenshotImg');
    if (!img || !img.src) return;
    if (currentShift && currentShift.pancafe_screenshot_filename) return;
    if (!img.src.startsWith('data:')) return;
    const preview = document.getElementById('screenshotPreview');
    if (!preview || preview.style.display === 'none') return;
    try {
        const resp = await fetch(img.src);
        const blob = await resp.blob();
        if (blob.size < 100) return;
        const fd = new FormData();
        fd.append('image', blob, 'pancafe.png');
        fd.append('type', 'pancafe');
        if (currentShift) fd.append('shift_id', currentShift.shift_id);
        const res = await fetch('/api/upload-screenshot', { method: 'POST', body: fd });
        const data = await res.json();
        if (data.success && currentShift) {
            currentShift.pancafe_screenshot_filename = data.filename;
            showScreenshotPreview('/uploads/' + data.filename);
            triggerAutoSave();
            console.log('Pancafe screenshot uploaded on close:', data.filename);
            showToast('Pancafe screenshot uploaded', 'success');
        } else {
            showToast('Pancafe screenshot upload failed', 'warning');
        }
    } catch (e) {
        console.warn('Failed to upload pancafe screenshot during close:', e);
        showToast('Pancafe screenshot upload error', 'warning');
    }
}

async function closeShift() {
    const employee = document.getElementById('employeeSelect').value;
    if (!employee) { showToast('Select an employee name','error'); return; }

    const cash = parseFloat(document.getElementById('cashInput').value) || 0;
    const online = parseFloat(document.getElementById('onlineInput').value) || 0;
    const posAmount = parseFloat(document.getElementById('actualPosInput').value) || 0;
    const grandText = document.getElementById('grandTotal').textContent.replace(/[^0-9.-]/g,'');
    const grandTotal = parseFloat(grandText) || 0;
    const expenses = parseFloat(document.getElementById('summaryExpenses').textContent.replace(/,/g,'')) || 0;
    const payTarget = grandTotal - expenses;

    if (Math.abs(cash + online + posAmount - payTarget) > 0.01) {
        showToast(`Payment mismatch! Cash (PKR ${cash.toFixed(2)}) + Online (PKR ${online.toFixed(2)}) + POS (PKR ${posAmount.toFixed(2)}) = PKR ${(cash+online+posAmount).toFixed(2)} must equal Grand Total minus Expenses PKR ${payTarget.toFixed(2)}`,'error');
        return;
    }

    const pinOk = await requireEmployeePin(employee);
    if (!pinOk) return;

    const confirmed = await showConfirmModal();
    if (!confirmed) return;

    const btn = document.getElementById('closeShiftBtn');
    btn.disabled = true;
    btn.innerHTML = '<span class="spinner"></span> Waiting for pancafe screenshot...';

    if (_uploadingScreenshot) {
        let waited = 0;
        while (_uploadingScreenshot && waited < 5000) {
            await new Promise(r => setTimeout(r, 200));
            waited += 200;
        }
    }

    btn.innerHTML = '<span class="spinner"></span> Uploading pancafe screenshot...';

    await _ensurePancafeUploaded();

    btn.innerHTML = '<span class="spinner"></span> Capturing screenshot...';

    await captureAndUploadScreenshot();

    btn.innerHTML = '<span class="spinner"></span> Closing...';

    const payload = buildShiftPayload();

    try {
        const res = await fetch('/api/shift/close', {
            method:'POST', headers:{'Content-Type':'application/json'},
            body: JSON.stringify({shift: payload})
        });
        const data = await res.json();
        if (data.success) {
            if (tabCoordinator) tabCoordinator.deactivate();
            // Clear local draft now that shift is closed
            clearLocalDraft(payload.shift_id);
            currentShift = null;
            lastShift = data.shift;
            // Persist still-running sessions so their alarms ring across the
            // close -> (reload) -> next-start window; they re-merge on start.
            _persistPendingSessions();
            setStatus('closed','Shift Closed');
            if (data.sync_success) {
                showToast(data.message || 'Shift closed!','success');
            } else {
                showToast(data.message || 'Shift closed!','success', 6000);
                showToast(data.warning || 'Sync unavailable','warning', 8000);
            }
            renderClosedShiftView(data.shift);
            toggleFormMode();
            showClosedShiftView();
        } else {
            showToast(data.error || 'Failed to close shift','error');
        }
    } catch(e) {
        showToast('Server error while closing shift','error');
    } finally {
        btn.disabled = false;
        btn.innerHTML = '<span class="btn-icon">🔒</span> Close Shift';
    }
}

function populateFormFromShift(s) {
    if (!s) return;
    if (s.employee_name) {
        document.getElementById('employeeSelect').value = s.employee_name;
        syncDropdown(document.getElementById('employeeSelect'));
    }
    if (s.shift_name && s.shift_timing) {
        const shiftVal = `${s.shift_name} (${s.shift_timing})`;
        const opt = Array.from(document.getElementById('shiftSelect').options).find(o => o.value === shiftVal);
        if (opt) document.getElementById('shiftSelect').value = shiftVal;
        syncDropdown(document.getElementById('shiftSelect'));
    }
    const mkPkgRow = (name, amt) => {
        const totalPCs = config.total_pcs || 27;
        const pcOpts = Array.from({length:totalPCs}, (_, i) => `<option value="PC #${i+1}" ${name === `PC #${i+1}` ? 'selected' : ''}>PC #${i+1}</option>`).join('');
        const pkgOpts = sortPackages(config.packages).map(p => `<option value="${p.price}" ${parseFloat(amt) === p.price ? 'selected' : ''}>${p.hz} ${p.hrs} - PKR ${p.price}</option>`).join('');
        return `<td><select class="pkg-name" onchange="pcNameSelected(this)"><option value="">PC #</option>${pcOpts}</select></td><td><select class="pkg-amount" onchange="recalcTotals()"><option value="">Select Package</option>${pkgOpts}</select></td><td><button class="btn-del-row" onclick="this.closest('tr').remove(); recalcTotals();">✕</button></td>`;
    };
    const morningBody = document.getElementById('morningBody');
    morningBody.innerHTML = '';
    (s.morning_packages || []).forEach(p => {
        const row = document.createElement('tr');
        row.innerHTML = mkPkgRow(p[0], parseFloat(p[1]).toFixed(2));
        morningBody.appendChild(row);
        initCustomDropdowns(row);
        initPkgAmountEnter(row, 'morning');
        syncDropdown(row.querySelector('.pkg-name'));
        syncDropdown(row.querySelector('.pkg-amount'));
    });
    const nighterBody = document.getElementById('nighterBody');
    nighterBody.innerHTML = '';
    (s.nighter_packages || []).forEach(p => {
        const row = document.createElement('tr');
        row.innerHTML = mkPkgRow(p[0], parseFloat(p[1]).toFixed(2));
        nighterBody.appendChild(row);
        initCustomDropdowns(row);
        initPkgAmountEnter(row, 'nighter');
        syncDropdown(row.querySelector('.pkg-name'));
        syncDropdown(row.querySelector('.pkg-amount'));
    });
    const ps5Body = document.getElementById('ps5Body');
    ps5Body.innerHTML = '';
    (s.ps5_sessions || []).forEach(p => {
        const storedDur = parseInt(p[5]) || 1;
        const durMax = Math.max(6, storedDur);
        const durOpts = Array.from({length: durMax},(_,i)=>`<option value="${i+1}" ${storedDur===i+1?'selected':''}>${i+1} hr${i>0?'s':''}</option>`).join('');
        const isExtended = p[6] ? true : false;
        const row = document.createElement('tr');
        row.dataset.state = 'editing';
        row.dataset.amountManual = p[8] ? 'true' : 'false';
        row.dataset.isExtended = isExtended ? 'true' : 'false';
        row.dataset.rowId = p[7] || '';
        if (p[7] && ps5EndPins[p[7]] != null) row.dataset.endMs = String(ps5EndPins[p[7]]);
        if (isExtended) row.classList.add('ps5-extended');
        const extBadge = isExtended ? '<span class="ext-badge">⚡ EXT</span>' : '';
        const ps5Opts = (config.ps5_numbers || ['Left', 'Right', 'PC']).map(v => `<option value="${v}" ${(p[0]||'')===v?'selected':''}>${v}</option>`).join('');
        row.innerHTML = `<td><select class="ps5-number" onchange="handlePS5NumberChange(this)">${ps5Opts}</select></td><td><select class="ps5-ctrl" onchange="recalcPS5RowAmount(this); autoCalcPS5()">${[1,2,3,4].map(v => `<option value="${v}" ${p[1]==v?'selected':''}>${v}</option>`).join('')}</select></td><td><input type="time" class="ps5-start" value="${p[2]||''}" onchange="calcPS5EndTime(this); autoCalcPS5()"></td><td><select class="ps5-duration" onchange="recalcPS5RowAmount(this); calcPS5EndTime(this); autoCalcPS5()">${durOpts}</select></td><td><input type="time" class="ps5-end" readonly tabindex="-1" value="${p[3]||''}"></td><td><input type="number" class="ps5-amount" step="0.01" min="0" placeholder="Amount" style="background:rgba(0,0,0,0.2);color:var(--gold);font-weight:700;" onchange="this.closest('tr').dataset.amountManual='true'; this.classList.add('ps5-amount-manual'); autoCalcPS5()"></td><td>${extBadge}</td><td><button class="btn-del-row" onclick="this.closest('tr').remove(); autoCalcPS5(); syncTimerRegistry();">✕</button></td>`;
        ps5Body.appendChild(row);
        initCustomDropdowns(row);
        // A manually entered amount is authoritative — never recompute it away.
        if (p[8]) {
            const amtInput = row.querySelector('.ps5-amount');
            amtInput.value = (parseFloat(p[4]) || 0).toFixed(2);
            amtInput.classList.add('ps5-amount-manual');
        } else {
            recalcPS5RowAmount(row);
        }
        syncDropdown(row.querySelector('.ps5-ctrl'));
        syncDropdown(row.querySelector('.ps5-duration'));
        syncDropdown(row.querySelector('.ps5-number'));
        if ((p[0]||'') === 'PC') row.classList.add('ps5-pc-row');
    });
    renderInventory(s.inventory_items_snapshot || config.inventory_items);
    if (s.inventory && s.inventory.length > 0) {
        s.inventory.forEach(inv => {
            const el = document.querySelector(`.inv-opening[data-item="${escHtml(inv[0])}"]`);
            if (el) {
                el.value = inv[1] || 0;
                const r = el.closest('tr');
                r.querySelector('.inv-restock').value = inv[2] || 0;
                r.querySelector('.inv-closing').value = inv[3] || 0;
                recalcInvSold(r.querySelector('.inv-closing'));
            }
        });
    } else if (lastShift && lastShift.inventory) {
        lastShift.inventory.forEach(i => {
            const name = i[0];
            const closing = parseInt(i[3]) || 0;
            const el = document.querySelector(`.inv-opening[data-item="${escHtml(name)}"]`);
            if (el) el.value = closing;
        });
    }
    const expenseBody = document.getElementById('expenseBody');
    expenseBody.innerHTML = '';
    (s.expenses || []).forEach(e => {
        const row = document.createElement('tr');
        row.innerHTML = `<td><input type="text" class="exp-desc" value="${escHtml(e[0]||'')}" oninput="autoCalcExpenses()"></td><td><input type="number" class="exp-amount" value="${parseFloat(e[1]).toFixed(2)}" step="0.01" min="0" oninput="autoCalcExpenses()"></td><td><button class="btn-del-row" onclick="this.closest('tr').remove(); autoCalcExpenses();">✕</button></td>`;
        expenseBody.appendChild(row);
    });
    document.getElementById('topupInput').value = s.topup_sale || 0;
    document.getElementById('cafeteriaInput').value = s.cafeteria_sale || 0;
    document.getElementById('cashInput').value = s.cash_received || 0;
    document.getElementById('onlineInput').value = s.online_payments || 0;
    document.getElementById('actualPosInput').value = s.actual_pos_amount || 0;
    document.getElementById('totalTaxAmountInput').value = s.total_tax_amount || 0;
    if (s.pancafe_screenshot_filename) {
        showScreenshotPreview('/uploads/' + s.pancafe_screenshot_filename);
    } else {
        resetScreenshotPreview();
    }
    recalcTotals();
    syncTimerRegistry();
}

async function continueShift(shiftId) {
    try {
        const res = await fetch(`/api/shifts/${shiftId}`);
        const data = await res.json();
        if (!data.success) { showToast('Shift not found','error'); return; }
        currentShift = data.shift;
        const fromLocal = await reconcileLocalDraft(data.shift);
        if (!fromLocal) populateFormFromShift(data.shift);
        showFormView();
        toggleFormMode();
        showToast('Shift loaded. Continue editing.','success');
        if (tabCoordinator) tabCoordinator.activate(currentShift.shift_id);
    } catch(e) {
        showToast('Failed to load shift','error');
    }
}

function showConfirmModal() {
    return new Promise((resolve) => {
        const overlay = document.getElementById('confirmModal');
        const yesBtn = document.getElementById('confirmYesBtn');
        const noBtn = document.getElementById('confirmNoBtn');
        const grandText = document.getElementById('grandTotal').textContent;

        overlay.classList.add('show');
        document.getElementById('confirmGrandTotal').textContent = grandText;

        const cleanup = (result) => {
            overlay.classList.remove('show');
            yesBtn.onclick = null;
            noBtn.onclick = null;
            resolve(result);
        };

        yesBtn.onclick = () => cleanup(true);
        noBtn.onclick = () => cleanup(false);
    });
}

