    if (listId === 'settingsEmployees') {
        arr = settingsData.employees;
    } else if (listId === 'settingsPackages') {
        arr = settingsData.packages;
    } else if (listId === 'settingsPS5Numbers') {
        arr = settingsData.ps5_numbers;
    } else {
        arr = settingsData.inventory_items;
    }
    arr.splice(idx, 1);
